-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/

-- colors.lua is generated by scripts/theme.sh (matugen); fall back to defaults if missing
local ok, C = pcall(require, "colors")
if not ok then
    C = { active1 = "rgba(33ccffee)", active2 = "rgba(00ff99ee)", inactive = "rgba(595959aa)", shadow = "rgba(1a1a1aee)" }
end

hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            active_border   = { colors = { C.active1, C.active2 }, angle = 45 },
            inactive_border = C.inactive,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = C.shadow,
        },

        -- blur shows through transparent windows (ghostty) and layers
        blur = {
            enabled   = true,
            size      = 6,
            passes    = 3,
            vibrancy  = 0.1696,
            new_optimizations = true,
        },
    },

    misc = {
        force_default_wallpaper = -1,    -- Set to 0 or 1 to disable the anime mascot wallpapers
        disable_hyprland_logo   = false, -- If true disables the random hyprland logo / anime girl background. :(
        vrr = 2
    },
})

